"use client";

import { useCallback, useEffect, useMemo, useState } from "react";
import { useSearchParams } from "next/navigation";
import { AlertTriangle, Bike, CarFront, CheckCircle2, Clock3, Navigation, PackageCheck, Radio, RefreshCw, Route, ShieldAlert, Truck, UserRound, WifiOff, X } from "lucide-react";
import { authenticatedFetch } from "@/lib/api-client";
import { Badge, Button, Card, EmptyState, PageHeader, PageSkeleton, SearchField, SectionCard, StatusBadge, Tabs } from "@/components/ui";
import { LottieEmptyState } from "@/components/spotly-lottie";
import { formatCurrency } from "@/lib/format";
